mapper.select:
SELECT r.*,
       u.user_name AS userName,
       u.phonenumber
FROM furniture_ai_call_records r
LEFT JOIN sys_user u ON r.user_id = u.user_id


        AND r.user_id = #{userId}


        AND r.create_time >= #{startTime}


        AND r.module = #{module}


        AND r.status = #{status}


ORDER BY r.id DESC
